#include <bits/stdc++.h>
using namespace std;
#define ll long long int
ll rec(ll i1,ll i2,ll n,vector<ll> &pref){
    // return
    
    ll i3 = n-i1-i2;
    ll s6 = i1;
    ll s4 = 2*i2;
    ll s3 = 3*i3;
    ll sum6 = pref[s6];
    ll sum4 = pref[s6+s4]-pref[s6];
    ll sum3 = pref[s6+s4+s3]-pref[s6+s4];
    return (6LL*sum6)+(4LL*sum4)+(3LL*sum3);
}
void solve(){
    ll n;
    cin>>n;
    vector<ll> a(3*n);
    for(int i=0;i<3*n;i++) cin>>a[i];
    sort(a.begin(),a.end(),greater<ll>());
    vector<ll> pref(3*n+1);
    for(int i=0;i<3*n;i++){
        pref[i+1]=pref[i]+a[i];
    }
    // for(int i=0;i<3*n;i++) cout<<pref[i]<<" ";
    ll ans = LLONG_MIN;
    ll i2 = n;
    for(int i=0;i<=n;i++){
        i2 = min(i2,n-i);
        while(i2>0){
            ll cur = rec(i,i2,n,pref);
            ll t1 = rec(i,i2-1,n,pref);
            // cout<<"cur "<<cur<<"t1 "<<t1<<endl;
            if(t1>=cur){
                i2--;
            }
            else{
                break;
            }
        }
        ans = max(ans,rec(i,i2,n,pref));
    }
    cout<<ans<<endl;
}
int main() {
	// your code goes here
    ll t;
    cin>>t;
    while(t--){
        solve();
    }
}
